item.aggregated_output:
401	    templates: readonly string[] | undefined;
402	    pages: Readonly<Record<string, string>>;
403	  },
404	  _optional: Record<string, never> = {}
405	): string[] {
406	  const { templates, pages } = required;
407	  if (!templates) return [];
408	
409	  const errors: string[] = [];
410	  for (const entry of templates) {
411	    const pageId = entry.replace(/\.html$/, "");
412	    const html = pages[pageId];
413	    if (html === undefined) {
414	      errors.push(`theme.json templates entry '${entry}' has no matching pages/${pageId}.html file`);
415	      continue;
416	    }
417	    if (markersOfType(html, TEMPLATE_SLOT_MARKER_TYPE).length === 0) {
418	      errors.push(
419	        `pages/${pageId}.html is declared in theme.json templates but has no {"type":"${TEMPLATE_SLOT_MARKER_TYPE}"} marker`
420	      );
421	    }
422	  }
423	  return errors;
424	}
