426	/**
427	 * Read the static tier's assets as one unit, or nothing at all for any other tier.
428	 *
429	 * A static theme is a different kind of artifact from every other tier — already-complete HTML
430	 * documents plus their partials and an optional light-token variant, rather than a route map of
431	 * templates a rendering engine fills in — so none of this shares a branch with the other tiers.
432	 * Kept out of {@link loadTheme}, tier check included, because inlining it there made one function
433	 * responsible for four unrelated on-disk layouts and left the caller re-testing the tier three
434	 * separate times.
435	 *
436	 * Errors are returned rather than thrown, matching {@link loadTheme}'s contract that one bad theme
437	 * degrades to `status: "invalid"` instead of breaking discovery for every other theme.
438	 *
439	 * @complexity O(f) in the theme folder's entries, each read at most once.
440	 * @overallScore 100
441	 */
442	function loadStaticTierAssets(
443	  required: {
444	    themeDir: string;
445	    tier: ThemeTier;
446	    slots?: Record<string, ThemeSlotDescriptor>;
447	    templates?: string[];
448	  },
449	  _optional: Record<string, never> = {}
450	): StaticTierAssets {
451	  const { themeDir, tier, slots, templates } = required;
452	  if (tier !== "static") return NO_STATIC_TIER_ASSETS;
453	
454	  const errors: string[] = [];
455	  const tokensLight = readLightTokens({ themeDir, errors });
456	
457	  // REQ-01's spirit, not its exact home+entry pair: a static theme's minimum is one page to
458	  // actually show, not a route id a templating engine would fill in.
459	  const pages: Record<string, string> = {};
460	  const pagesDir = join(themeDir, "pages");
461	  if (existsSync(pagesDir)) {
462	    for (const file of readdirSync(pagesDir)) {
463	      if (file.endsWith(".html")) {
464	        pages[file.slice(0, -".html".length)] = readFileSync(join(pagesDir, file), "utf8");
465	      }
466	    }
467	  }
468	  if (!pages.index) errors.push("pages/index.html is required");
469	
470	  errors.push(...validateTemplateDeclarations({ templates, pages }));
471	
472	  // Root partials (`nav`, `footer`, and anything else the manifest declares) live at the theme root,
473	  // not under pages/, because a static page embeds them via a `{"type":"partial"}` marker the
474	  // renderer resolves rather than a template-include directive baked in at author time. A theme with
475	  // no `slots` block gets DEFAULT_THEME_SLOTS, which is the nav/footer pair this scan used to hardcode.
476	  const partials = loadSlotPartials({ themeDir, slots: slots ?? DEFAULT_THEME_SLOTS });
477	
478	  return { tokensLight, pages, partials, errors };
479	}
