481	/**
482	 * Load one theme folder. Returns a DiscoveredTheme with `status: "invalid"` and
483	 * a populated `errors` list instead of throwing, so one bad theme never breaks
484	 * discovery (SPEC-004 REQ-10 spirit).
485	 */
486	export function loadTheme(
487	  required: { themeDir: string; id: string; source: "built-in" | "site" },
488	  _optional: Record<string, never> = {}
489	): DiscoveredTheme {
490	  const { themeDir, id, source } = required;
491	  const errors: string[] = [];
492	  const empty: ThemeManifest = { id, name: id, version: "0.0.0", tier: "declarative", engine: 1 };
493	
494	  let manifest = empty;
495	  try {
496	    const raw = readJson(join(themeDir, "theme.json"));
497	    if (!isObject(raw)) throw new Error("theme.json is not an object");
498	    manifest = {
499	      id: String(raw.id ?? id),
500	      name: String(raw.name ?? id),
501	      version: String(raw.version ?? "0.0.0"),
502	      tier: parseTier(raw.tier),
503	      engine: typeof raw.engine === "number" ? raw.engine : 1,
504	      description: typeof raw.description === "string" ? raw.description : undefined,
505	      fonts: Array.isArray(raw.fonts) ? raw.fonts.map(String) : undefined,
506	      regions: Array.isArray(raw.regions) ? raw.regions.map(String) : undefined,
507	      skipLiquidAllowlist: raw.skipLiquidAllowlist === true,
508	      // No `postTemplate`/`pageTemplate` back-compat aliases (2026-08-11 unification, owner's
509	      // standing rule on this contract: strictness over compat code). A manifest still carrying the
510	      // retired spelling simply loads with no templates, same as one that never declared any —
511	      // `check:embed-marker-drift` is what catches a manifest that needed converting, not this parse.
512	      templates: Array.isArray(raw.templates) ? raw.templates.map(String) : undefined,
513	      modes: Array.isArray(raw.modes) ? raw.modes.map(String) : undefined,
514	      defaultMode: typeof raw.defaultMode === "string" ? raw.defaultMode : undefined,
515	      slots: parseSlots(raw.slots),
516	    };
517	    if (manifest.id !== id) errors.push(`theme.json id '${manifest.id}' must equal folder name '${id}'`);
518	    // A `defaultMode` the theme ships no tokens for would silently render the base `:root` block
519	    // while the manifest claims otherwise — the exact "declared but unreachable" failure wiring
520	    // these fields was meant to end, so it fails the theme loudly instead of falling back.
521	    if (manifest.defaultMode !== undefined && !(manifest.modes ?? []).includes(manifest.defaultMode)) {
522	      errors.push(
523	        `theme.json defaultMode '${manifest.defaultMode}' is not listed in modes [${(manifest.modes ?? []).join(", ")}]`
524	      );
525	    }
526	  } catch (err) {
527	    errors.push(`theme.json: ${(err as Error).message}`);
528	  }
529	
530	  let tokens: ThemeTokens = {};
531	  try {
532	    const raw = readJson(join(themeDir, "tokens.json"));
533	    if (!isObject(raw)) throw new Error("tokens.json is not an object");
534	    tokens = Object.fromEntries(Object.entries(raw).map(([k, v]) => [k, String(v)]));
535	  } catch (err) {
536	    errors.push(`tokens.json: ${(err as Error).message}`);
537	  }
538	
539	  // The static tier's whole on-disk layout — light tokens, pages/, root partials — loaded in one
540	  // call rather than as branches threaded through the tier-agnostic loading below. Empty for every
541	  // other tier, so nothing here needs to re-test which tier this is.
542	  const { tokensLight, pages, partials, errors: staticErrors } = loadStaticTierAssets({
543	    themeDir,
544	    tier: manifest.tier,
545	    slots: manifest.slots,
546	    templates: manifest.templates,
547	  });
548	  errors.push(...staticErrors);
549	
550	  const templates: Record<string, TemplateNode> = {};
551	  const liquidTemplates: Record<string, string> = {};
552	  const handlebarsTemplates: Record<string, string> = {};
553	  const templatesDir = join(themeDir, "templates");
554	  if (existsSync(templatesDir)) {
555	    for (const file of readdirSync(templatesDir)) {
556	      if (file.endsWith(".json")) {
557	        const templateId = file.slice(0, -".json".length);
558	        try {
559	          templates[templateId] = readJson(join(templatesDir, file));
560	        } catch (err) {
561	          errors.push(`templates/${file}: ${(err as Error).message}`);
562	        }
563	      } else if (file.endsWith(".liquid")) {
564	        // Templated tier (ADR-020): raw LiquidJS source, rendered by the engine
565	        // in render.ts. C6/REQ-06 lint-before-publish: reject any tag/filter
566	        // outside the ADR-020 §3 allowlist before the theme can load as valid —
567	        // unless the theme opted out via `skipLiquidAllowlist` (see ThemeManifest
568	        // doc comment: the runtime's other Tier-2 guardrails — worker isolation,
569	        // filesystem lockdown, memory/render/parse limits — still apply either way).
570	        const templateId = file.slice(0, -".liquid".length);
571	        const source = readFileSync(join(templatesDir, file), "utf8");
572	        const violations = manifest.skipLiquidAllowlist ? [] : lintLiquidTemplate(source);
573	        if (violations.length > 0) {
574	          errors.push(`templates/${file}: ${violations.join("; ")}`);
575	        } else {
576	          liquidTemplates[templateId] = source;
577	        }
578	      } else if (file.endsWith(".hbs") || file.endsWith(".handlebars")) {
579	        // Handlebars tier (ADR-020): raw Handlebars source, rendered by the
580	        // isolated worker in `server/http/site/handlebars-worker.ts`. Exactly the
581	        // same lint-before-publish contract the `.liquid` branch above applies,
582	        // against the Handlebars-specific allowlist — a disallowed helper, a
583	        // partial, a decorator, or a `{{{raw}}}` output outside the one sanctioned
584	        // path fails the theme rather than reaching the compiler. Both extensions
585	        // are accepted (Handlebars' ecosystem uses them interchangeably) and map to
586	        // the same template-id namespace, so `home.hbs` and `home.handlebars` are
587	        // the same template id — the last one `readdirSync` yields wins, which is
588	        // why a theme should ship one or the other, not both.
589	        const ext = file.endsWith(".hbs") ? ".hbs" : ".handlebars";
590	        const templateId = file.slice(0, -ext.length);
591	        const source = readFileSync(join(templatesDir, file), "utf8");
592	        const violations = lintHandlebarsTemplate(source);
593	        if (violations.length > 0) {
594	          errors.push(`templates/${file}: ${violations.join("; ")}`);
595	        } else {
596	          handlebarsTemplates[templateId] = source;
597	        }
598	      }
599	    }
600	  }
601	  // A static theme has no `templates/` route map at all, so its required-file check is
602	  // `loadStaticTierAssets`'s job, not this one's.
603	  if (manifest.tier !== "static") {
604	    // REQ-01: a theme's required template minimum is home + entry (the base). C3:
605	    // post/page are optional specializations that fall through to entry (REQ-03).
606	    // The required set is tier-aware: templated themes ship `.liquid`, handlebars
607	    // themes ship `.hbs`, others JSON.
608	    const ext = manifest.tier === "templated" ? "liquid" : manifest.tier === "handlebars" ? "hbs" : "json";
609	    const requiredTemplates =
610	      manifest.tier === "templated" ? liquidTemplates : manifest.tier === "handlebars" ? handlebarsTemplates : templates;
611	    if (!requiredTemplates.home) errors.push(`templates/home.${ext} is required`);
612	    if (!requiredTemplates.entry) errors.push(`templates/entry.${ext} is required`);
613	  }
614	
615	  let css = "";
616	  // Static themes keep CSS under css/styles.css (alongside sibling js/ and pages/
617	  // folders) rather than a lone file at the theme root — the root-level convention
618	  // fits every other tier's flat, single-stylesheet shape; static ships a whole
619	  // small multi-file project instead.
620	  const cssPath = join(themeDir, manifest.tier === "static" ? "css/styles.css" : "styles.css");
621	  if (existsSync(cssPath)) css = readFileSync(cssPath, "utf8");
622	
623	  const loaded: DiscoveredTheme = {
624	    manifest,
625	    dir: themeDir,
626	    tokens,
627	    tokensLight,
628	    templates,
629	    liquidTemplates,
630	    handlebarsTemplates,
631	    pages,
632	    partials,
633	    css,
634	    source,
635	    status: errors.length === 0 ? "valid" : "invalid",
636	    errors,
637	  };
638	
639	  return loaded;
640	}
641	
642	/**
643	 * Discover every theme folder under `dir`. Missing dir ⇒ empty list (a site
644	 * served without a themes/ dir is legal, SPEC-004 REQ-05).
645	 *
646	 * `exclude` skips named subdirectories that aren't themes themselves — used by
647	 * {@link discoverAllBuiltInThemes} to keep the engine-specific subfolders
648	 * (`templated/`, `handlebars/`) from being scanned as (invalid) top-level theme
649	 * candidates when it also scans them directly as their own theme roots.
650	 */
651	export function discoverThemes(
652	  required: { dir: string; source: "built-in" | "site"; exclude?: readonly string[] },
653	  _optional: Record<string, never> = {}
654	): DiscoveredTheme[] {
655	  const { dir, source, exclude } = required;
656	  if (!existsSync(dir)) return [];
657	  return readdirSync(dir)
658	    .filter((name) => {
659	      if (exclude?.includes(name)) return false;
660	      const full = join(dir, name);
661	      return statSync(full).isDirectory();
662	    })
663	    .map((name) => loadTheme({ themeDir: join(dir, name), id: name, source }))
664	    .sort((a, b) => a.manifest.id.localeCompare(b.manifest.id));
665	}
666	
667	/**
668	 * Named engine-specific subfolders under a themes root, one per {@link ThemeTier} except `code`
669	 * (not built yet) — every tier's themes live under its own subfolder so `themes/` doesn't mix
670	 * formats in one flat listing (2026-08-10: `declarative` moved off the bare top level, and the
671	 * LiquidJS-tier folder renamed from `liquidjs/` to `templated/` to match its `ThemeTier` value —
672	 * `templated` names the tier, not the engine, so more templating engines can land under this same
673	 * folder later without another rename). Scanning a missing subfolder is a no-op (`discoverThemes`'s
674	 * own missing-dir ⇒ empty-list behavior), so adding an engine here ahead of its first theme costs
675	 * nothing.
676	 *
677	 * Exported because it is also the containment boundary the `themes` agent-tool domain enforces
678	 * (`agent-tools.ts`/`tool-registrations.ts`): a theme folder that is not a direct child of the
679	 * themes root or of one of THESE subfolders is not a recognized theme root, and no agent-driven file
680	 * write may resolve into it.
681	 */
682	export const ENGINE_SUBFOLDERS = ["declarative", "templated", "handlebars", "static"] as const;
683	
684	/**
685	 * The pristine-originals catalog under a themes root: shipped themes kept untouched so a copy can
686	 * always be compared against, reset to, or re-forked from what it started as.
687	 *
688	 * It is NOT a tier and NOT a theme — it holds its own `<tier>/<theme>/` tree — so discovery skips it
689	 * outright. A catalog theme is never runnable, never listed, and never the active theme; it becomes
690	 * either of those only by being COPIED into a real tier folder, which is the whole point: editing
691	 * your copy can never damage the thing you'd want to compare it against.
692	 *
693	 * The `__` prefix is load-bearing rather than decorative. It makes "this is not an installed theme"
694	 * a property of the name that any code path can check, instead of a list every new write path has to
695	 * remember to consult — see the containment note on {@link ENGINE_SUBFOLDERS}, which already refuses
696	 * agent-driven writes to anything that isn't a direct child of the root or of an engine subfolder.
697	 */
698	export const THEME_CATALOG_DIR = "__original-themes__";
699	
700	/**
701	 * The local marketplace fixture root under a themes root — a stand-in for a remote theme
702	 * marketplace (see `src/themes/__marketplace__/README.md` for what a real one would still need:
703	 * network, search, versioning). Same shape as {@link THEME_CATALOG_DIR}: `<tier>/<id>/` per
704	 * {@link ENGINE_SUBFOLDERS}, and the same NOT-a-tier/NOT-a-theme status, for the same reason —
705	 * discovery skips it outright. A marketplace entry becomes a real, runnable theme only via
706	 * `downloadMarketplaceTheme` (`marketplace.ts`), which copies it into both {@link THEME_CATALOG_DIR}
707	 * and a live tier folder under a freshly assigned id ({@link nextAvailableThemeId}).
708	 */
709	export const MARKETPLACE_CATALOG_DIR = "__marketplace__";
710	
711	/**
712	 * Discover every built-in theme across the top-level (declarative) folder plus every engine
713	 * subfolder in {@link ENGINE_SUBFOLDERS}. The one call site every composition root should use
714	 * instead of a raw {@link discoverThemes} call, so the liquidjs/handlebars split is a detail this
715	 * function owns rather than something every caller re-derives.
716	 */
717	export function discoverAllBuiltInThemes(
718	  required: { dir: string; source: "built-in" | "site" },
719	  _optional: Record<string, never> = {}
720	): DiscoveredTheme[] {
721	  const { dir, source } = required;
722	  const topLevel = discoverThemes({
723	    dir,
724	    source,
725	    exclude: [...ENGINE_SUBFOLDERS, THEME_CATALOG_DIR, MARKETPLACE_CATALOG_DIR],
726	  });
727	  const engineThemes = ENGINE_SUBFOLDERS.flatMap((sub) => discoverThemes({ dir: join(dir, sub), source }));
728	  return [...topLevel, ...engineThemes].sort((a, b) => a.manifest.id.localeCompare(b.manifest.id));
729	}
730	
731	/**
732	 * Assign a folder-safe id for a NEW theme being installed under `themesRoot`, guaranteeing it does
733	 * not collide with anything already there. Theme ids are unique per FOLDER, not globally (see
734	 * {@link duplicateThemeIds}) — the fix is to never create a second folder claiming an id already in
735	 * use, which is what this makes possible at the one call site that creates theme folders today
736	 * (`downloadMarketplaceTheme`, `marketplace.ts`).
737	 *
738	 * Checks BOTH the installed tier folder (`<themesRoot>/<tier>/<id>`) and the catalog
739	 * (`<themesRoot>/{@link THEME_CATALOG_DIR}/<tier>/<id>`) — a download writes to both in lockstep, so
740	 * a folder existing in only one of them (e.g. a previous run left the pair out of sync) still counts
741	 * as taken. Picking an id free in one and not the other would recreate the exact desync this exists
742	 * to prevent.
743	 *
744	 * `desiredId` is only ever SUFFIXED, never renumbered: an id that already ends in a digit (e.g.
745	 * `basic9`) gets `basic9-1` on collision, not `basic10` — the suffix always unambiguously means "the
746	 * Nth copy of this id", never a digit that could be mistaken for part of the original id.
747	 *
748	 * @param required.desiredId - The id to try first (typically a marketplace fixture's own `theme.json` id).
749	 * @param required.themesRoot - The themes root both the tier folder and the catalog live under.
750	 * @param required.tier - Which {@link ENGINE_SUBFOLDERS} tier's folder to check.
751	 * @returns `desiredId` if free, else `desiredId-1`, `desiredId-2`, … — the first free suffix.
752	 * @complexity O(n) filesystem existence checks, where n is the number of prior collisions on
753	 * `desiredId` (2 checks each); O(1) (2 checks) in the common, no-collision case.
754	 */
755	export function nextAvailableThemeId(
756	  required: { desiredId: string; themesRoot: string; tier: ThemeTier },
757	  _optional: Record<string, never> = {}
758	): string {
759	  const { desiredId, themesRoot, tier } = required;
760	  const isTaken = (id: string): boolean =>
761	    existsSync(join(themesRoot, tier, id)) || existsSync(join(themesRoot, THEME_CATALOG_DIR, tier, id));
762	
763	  if (!isTaken(desiredId)) return desiredId;
764	
765	  let suffix = 1;
766	  while (isTaken(`${desiredId}-${suffix}`)) suffix += 1;
767	  return `${desiredId}-${suffix}`;
768	}
769	
770	/**
771	 * Re-run discovery and refill `themes` IN PLACE with the result.
772	 *
773	 * Discovery is otherwise a boot-time snapshot: the composition root calls {@link
774	 * discoverAllBuiltInThemes} once and freezes the array into `RouteDeps.themes`, so a theme that
775	 * appears on disk afterwards — downloaded from the marketplace, copied from the originals catalog,
776	 * dropped in by hand, pulled in by git — is invisible until the process restarts. That is fine for a
777	 * server whose themes only ever ship with it, and wrong for one where copying a theme is a normal
778	 * thing a user does in the admin UI.
779	 *
780	 * Mutates rather than returns because `RouteDeps.themes` is a plain array every consumer already
781	 * holds a reference to and reads per request (`deps.themes.find(...)` at request time, not at
782	 * registration time). Refilling that one array updates every reader at once; handing back a new array
783	 * would update only whoever remembered to re-read it, which is the same staleness bug one level in.
784	 *
785	 * Returns what changed so a caller can report it — a rescan that silently finds nothing is
786	 * indistinguishable from a rescan that didn't run.
787	 */
788	export function rescanThemes(
789	  required: { themes: DiscoveredTheme[]; dir: string; source?: "built-in" | "site" },
790	  _optional: Record<string, never> = {}
791	): { added: string[]; removed: string[]; total: number } {
792	  const { themes, dir, source = "built-in" } = required;
793	  const before = new Set(themes.map((t) => t.manifest.id));
794	  const fresh = discoverAllBuiltInThemes({ dir, source });
795	  const after = new Set(fresh.map((t) => t.manifest.id));
796	
797	  themes.length = 0;
798	  themes.push(...fresh);
799	
800	  return {
801	    added: [...after].filter((id) => !before.has(id)).sort(),
802	    removed: [...before].filter((id) => !after.has(id)).sort(),
803	    total: fresh.length,
804	  };
805	}
806	
807	/**
808	 * Theme ids that more than one discovered theme claims.
809	 *
810	 * Ids are unique per FOLDER, not globally: `loadTheme` only checks that `theme.json`'s `id` equals
811	 * its own folder name, and {@link discoverAllBuiltInThemes} concatenates the top level with every
812	 * engine subfolder. So `static/nordic` and `handlebars/nordic` both load, both claim `nordic`, and
813	 * {@link findTheme} silently returns whichever sorts first — meaning `active_theme_id` can name two
814	 * different themes and the site renders one of them with no error anywhere.
815	 *
816	 * Surfaced rather than resolved: picking a winner here would hide the collision, and the real fix is
817	 * assigning a unique id when the theme is created (a download/copy appends `-1`, `-2`, …). This is
818	 * what lets the admin say so instead of rendering the wrong theme quietly.
819	 */
820	export function duplicateThemeIds(themes: DiscoveredTheme[]): string[] {

300	/** Everything only a static theme ships. Returned by {@link loadStaticTierAssets}. */
301	interface StaticTierAssets {
302	  tokensLight: ThemeTokens;
303	  pages: Record<string, string>;
304	  partials: Record<string, string>;
305	  /** Validation failures, for the caller to merge into the theme's own `errors`. */
306	  errors: string[];
307	}
308	
309	/** No static assets, for every tier that ships none. */
310	const NO_STATIC_TIER_ASSETS: StaticTierAssets = {
311	  tokensLight: {},
312	  pages: {},
313	  partials: {},
314	  errors: [],
315	};
316	
317	/**
318	 * Read `tokens.light.json`, a static theme's optional light-mode override set.
319	 *
320	 * Optional unlike `tokens.json`: absent is not an error, it just means the theme ships no light
321	 * variant, which leaves the map empty so no `:root` override block is emitted at all.
322	 */
323	function readLightTokens(
324	  required: { themeDir: string; errors: string[] },
325	  _optional: Record<string, never> = {}
326	): ThemeTokens {
327	  const { themeDir, errors } = required;
328	  const path = join(themeDir, "tokens.light.json");
329	  if (!existsSync(path)) return {};
330	  try {
331	    const raw = readJson(path);
332	    if (!isObject(raw)) throw new Error("tokens.light.json is not an object");
333	    return Object.fromEntries(Object.entries(raw).map(([k, v]) => [k, String(v)]));
334	  } catch (err) {
335	    errors.push(`tokens.light.json: ${(err as Error).message}`);
336	    return {};
337	  }
338	}
339	
340	/**
341	 * Read the root partial files a static theme's declared {@link ThemeManifest.slots} name.
342	 *
343	 * Before this, the partial scan was a hardcoded filename allowlist — `nav.html` or anything starting
344	 * with `footer` — which meant a theme could DECLARE a slot (`"sidebar": { "source": "sidebar.html" }`)
345	 * and have its file read by nothing, so the marker resolved empty with no error anywhere. Slots are
346	 * now the single source of truth for which root `.html` files are partials, which is what makes
347	 * adding a region to a copied theme a manifest edit rather than a code change here.
348	 *
349	 * A slot matches its own `source` plus the `<stem>-<variant>.html` convention `resolveSlots` already
350	 * falls back to for a variant with no explicit `variants` entry — so `footer.html` still pulls in
351	 * `footer-minimal.html`, and a new `sidebar` slot gets `sidebar-*.html` on the same terms rather than
352	 * a second, differently-shaped rule.
353	 */
354	function loadSlotPartials(
355	  required: { themeDir: string; slots: Record<string, ThemeSlotDescriptor> },
356	  _optional: Record<string, never> = {}
357	): Record<string, string> {
358	  const { themeDir, slots } = required;
359	  const descriptors = Object.values(slots);
360	  const stems = descriptors.map((slot) => slot.source.replace(/\.html$/, ""));
361	  const explicitVariants = new Set(descriptors.flatMap((slot) => Object.values(slot.variants ?? {})));
362	
363	  const partials: Record<string, string> = {};
364	  for (const file of readdirSync(themeDir)) {
365	    if (!file.endsWith(".html")) continue;
366	    const named = explicitVariants.has(file);
367	    const conventional = stems.some((stem) => file === `${stem}.html` || file.startsWith(`${stem}-`));
368	    if (!named && !conventional) continue;
369	    partials[file.slice(0, -".html".length)] = readFileSync(join(themeDir, file), "utf8");
370	  }
371	  return partials;
372	}
