377	/**
378	 * Validates the theme's `templates` array against its already-loaded `pages` (2026-08-11, owner
379	 * decision — see `ADS-memory/reports/continuity/2026-08-11-pages-template-decisions.md`, extended to
380	 * the unified single array by `ADS-memory/reports/design/2026-08-11-unified-content-marker-and-
381	 * templates.md`): a listed entry that resolves to no file, or to a file with zero `"content"`
382	 * markers, renders a structurally fine page with its actual content silently missing — "the worst
383	 * failure class this codebase keeps hitting", in the owner's own words, and the same class of bug
384	 * REQ-10's `pages/index.html is required` check exists to catch at load time rather than on a
385	 * visitor's page view.
386	 *
387	 * One field, one marker type, one call site — collapsed from the pre-unification version that took a
388	 * `fieldName`/`slotMarkerType` pair and was called twice (once for `postTemplate`/`"post"`, once for
389	 * `pageTemplate`/`"content"`). With only one array and one marker type left to check, parameterizing
390	 * either would just be indirection with a single value ever passed through it.
391	 *
392	 * Not itself tier-gated — `pages` is empty for every non-static theme (`loadStaticTierAssets`'s own
393	 * early return), so a non-static theme is already incapable of tripping this on a `templates` field it
394	 * isn't documented to declare; gating here too would just be a second copy of that same guarantee.
395	 *
396	 * @complexity O(t) over `templates`' length; each entry's marker scan is O(n) in that one page's HTML
397	 *   length (`markersOfType`), the same cost `resolveTemplate` already pays per request.
398	 */
399	function validateTemplateDeclarations(
400	  required: {
401	    templates: readonly string[] | undefined;
402	    pages: Readonly<Record<string, string>>;
403	  },
404	  _optional: Record<string, never> = {}
405	): string[] {
406	  const { templates, pages } = required;
407	  if (!templates) return [];
408	
409	  const errors: string[] = [];
410	  for (const entry of templates) {
411	    const pageId = entry.replace(/\.html$/, "");
412	    const html = pages[pageId];
413	    if (html === undefined) {
414	      errors.push(`theme.json templates entry '${entry}' has no matching pages/${pageId}.html file`);
415	      continue;
416	    }
417	    if (markersOfType(html, TEMPLATE_SLOT_MARKER_TYPE).length === 0) {
418	      errors.push(
419	        `pages/${pageId}.html is declared in theme.json templates but has no {"type":"${TEMPLATE_SLOT_MARKER_TYPE}"} marker`
420	      );
421	    }
422	  }
423	  return errors;
424	}
