135	/**
136	 * Sanitize a content `link` href (C7). Content is data, so an inline link is an
137	 * untrusted string: allow only in-page (`#…`), same-origin relative (`/…`),
138	 * `http(s)://`, and `mailto:` targets. Everything else — notably `javascript:`
139	 * and `data:` — collapses to `"#"` so a doc can never smuggle script into a page.
140	 */
141	function safeHref(value: JsonValue | undefined): string {
142	  if (typeof value !== "string") return "#";
143	  const href = value.trim();
144	  if (href.startsWith("/") || href.startsWith("#")) return href;
145	  if (/^https?:\/\//i.test(href) || /^mailto:/i.test(href)) return href;
146	  return "#";
147	}
