1388	 * @complexity O(1) beyond the resolved component's own rendering.
1389	 * @overallScore 100/100
1390	 */
1391	export function renderBlockSeam(ctx: SiteRenderContext, props: JsonObject): string {
1392	  if (typeof props.region === "string") {
1393	    return renderWidgetRegion({ ctx, regionKey: props.region });
1394	  }
1395	  const id = typeof props.component === "string" ? props.component : "";
1396	  const { component: _component, region: _region, ...rest } = props;
1397	  void _component;
1398	  void _region;
1399	  const component = COMPONENTS[id];
1400	  if (!component) return `<!-- unknown component: ${escapeHtml(id)} -->`;
1401	  return component(ctx, rest);
