1421	// ---------------------------------------------------------------------------
1422	// Template block tree
1423	// ---------------------------------------------------------------------------
1424	
1425	function renderBlock(node: TemplateNode, ctx: SiteRenderContext): string {
1426	  if (!isObject(node)) return "";
1427	
1428	  if (node.type === "component") {
1429	    const id = typeof node.id === "string" ? node.id : "";
1430	    const component = COMPONENTS[id];
1431	    if (!component) return `<!-- unknown component: ${escapeHtml(id)} -->`;
