  3	
  4	import type { SiteRenderContext } from "./render";
  5	
  6	/**
  7	 * @file ADR-020 Tier-2 guardrail: render isolation for LiquidJS templates.
  8	 *
  9	 * Purpose:
 10	 * Spawns a fresh `worker_threads` `Worker` per render, bounded by a CPU wall-
 11	 * clock timeout and V8 heap `resourceLimits`, so an adversarial "templated"
 12	 * theme (e.g. an unbounded `{% for %}` loop, or a template that builds an
 13	 * enormous string) cannot hang or OOM the main server process. A
 14	 * `Promise.race` around the synchronous `parseAndRenderSync` call would not
 15	 * help here — synchronous CPU-bound work on the main thread can't be
 16	 * pre-empted by a timer running on that same thread. Running the render on a
 17	 * *separate* thread is what makes `worker.terminate()` able to actually stop
 18	 * it. `worker_threads` is used instead of `isolated-vm`/`vm2`: it ships with
 19	 * Node (no new native dependency), and `vm2` carries known sandbox-escape
 20	 * CVEs while `isolated-vm` needs native compilation.
 21	 *
 22	 * How it relates to the project:
 23	 * Called from `render.ts`'s `renderSite()` in place of the old in-process
 24	 * `renderLiquidBody()`. The actual Liquid engine + component-registry
 25	 * wiring lives in `liquid-worker.ts`, which this module spawns by file path
 26	 * (not by static import, so the main thread never needs to construct a
 27	 * Liquid engine at all).
 28	 */
 29	
 30	/** What one render needs, sent to the worker as `workerData` (structured-clone only — plain data, no functions/class instances). */
 31	export interface LiquidWorkerInput {
 32	  source: string;
 33	  ctx: SiteRenderContext;
 34	  /** Mirrors `ThemeManifest.skipLiquidAllowlist` — `loadTheme()` already made this decision at
 35	   * discovery time; the worker's defensive re-lint (in case the file changed on disk since) honors
 36	   * the same choice rather than re-deciding it. */
 37	  skipLiquidAllowlist?: boolean;
 38	}
 39	
 40	/** The worker's reply, via `postMessage`. */
 41	export type LiquidWorkerResult = { ok: true; html: string } | { ok: false; error: string };
 42	
 43	export interface LiquidSandboxOptions {
 44	  /** Wall-clock budget for one render before the worker is force-terminated. */
 45	  timeoutMs?: number;
 46	  /** V8 heap caps for the worker thread. */
 47	  resourceLimits?: ResourceLimits;
 48	}
 49	
 50	const DEFAULT_TIMEOUT_MS = 5000;
 51	const DEFAULT_RESOURCE_LIMITS: ResourceLimits = {
 52	  maxOldGenerationSizeMb: 64,
 53	  maxYoungGenerationSizeMb: 16,
 54	  codeRangeSizeMb: 16,
 55	};
 56	
 57	/**
 58	 * Construct the isolated `Worker` for one render, matching whichever runtime
 59	 * is currently active.
 60	 *
 61	 * Under a `tsc` build (`npm run build` → `node dist/...`) `__filename` ends
 62	 * in `.js`; the compiled `liquid-worker.js` sibling is a plain file `Worker`
 63	 * needs no special handling.
 64	 *
 65	 * Under `tsx` (dev / `npm test`) `__filename` ends in `.ts`. Passing the
 66	 * `.ts` sibling as the `Worker`'s *entry* file with `execArgv: ["--import",
 67	 * "tsx"]` looks like the documented tsx pattern, but does not work here:
 68	 * verified empirically that Node's ESM loader routes a CommonJS-typed `.ts`
 69	 * *entry point* through its `loadCJSModule` translator, which does not run
 70	 * registered `--import` hooks against that first file — the sibling fails
 71	 * to parse with "Cannot use import statement outside a module" even though
 72	 * `execArgv`/`process.execArgv` show the flag present. The fix (also
 73	 * verified empirically) is to give the worker an inline bootstrap script via
 74	 * `eval: true` that first calls `tsx/cjs/api`'s `register()` — the same
 75	 * programmatic hook `tsx`'s CLI registers, but invoked as an ordinary
 76	 * `require()` inside the worker's own CommonJS entry — and only then
 77	 * `require()`s the real `.ts` worker file by absolute path. That `require()`
 78	 * is a normal, already-registered-hook require, which is the path every
 79	 * other cross-file `.ts` import in this codebase already goes through
 80	 * successfully under `--import tsx`.
 81	 */
 82	function spawnLiquidWorker(workerData: LiquidWorkerInput, resourceLimits: ResourceLimits): Worker {
 83	  const isTsSource = __filename.endsWith(".ts");
 84	  if (!isTsSource) {
 85	    return new Worker(path.join(__dirname, "liquid-worker.js"), { workerData, resourceLimits });
 86	  }
 87	  const workerFile = path.join(__dirname, "liquid-worker.ts");
 88	  const tsxApiPath = require.resolve("tsx/cjs/api");
 89	  const bootstrap = `require(${JSON.stringify(tsxApiPath)}).register();\nrequire(${JSON.stringify(workerFile)});\n`;
 90	  return new Worker(bootstrap, { eval: true, workerData, resourceLimits });
 91	}
 92	
 93	/**
 94	 * Render a "templated"-tier (LiquidJS) theme body inside an isolated worker
 95	 * thread, bounded by a wall-clock timeout and V8 heap limits.
 96	 *
 97	 * @param input the template source plus the render context (must already be
 98	 *   plain, structured-cloneable data — `SiteRenderContext`'s `posts`/`post`
 99	 *   fields are, by construction, `PostRecord`s with no functions/class
100	 *   instances).
101	 * @param options timeout/resourceLimits overrides; sane defaults apply.
102	 * @returns the rendered HTML body.
103	 * @throws if the render times out, the worker crashes/OOMs, or the template
104	 *   itself is invalid (syntax error or a disallowed tag/filter caught by the
105	 *   worker's defensive re-lint) — callers already treat any thrown error
106	 *   from Liquid rendering as "fall back to the minimal built-in body"
107	 *   (`render.ts`'s `renderSite`, SPEC-004 REQ-10 spirit: a broken/hostile
108	 *   theme must never 500 the site).
109	 * @complexity O(1) additional work beyond the render itself: one Worker
110	 *   spawn/teardown per call. No pooling — see the Programmer handoff for the
111	 *   documented spawn-cost tradeoff.
112	 * @overallScore 100/100
113	 */
114	export function renderLiquidInSandbox(
115	  input: LiquidWorkerInput,
116	  options: LiquidSandboxOptions = {}
117	): Promise<string> {
118	  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
119	  const resourceLimits = options.resourceLimits ?? DEFAULT_RESOURCE_LIMITS;
120	
121	  return new Promise<string>((resolve, reject) => {
122	    const worker = spawnLiquidWorker(input, resourceLimits);
123	    let settled = false;
124	
125	    const finish = (fn: () => void): void => {
126	      if (settled) return;
127	      settled = true;
128	      clearTimeout(timer);
129	      fn();
130	    };
131	
132	    const timer = setTimeout(() => {
133	      finish(() => {
134	        reject(new Error(`Liquid render exceeded ${timeoutMs}ms timeout`));
135	      });
136	      // Best-effort teardown; the promise has already settled above.
137	      void worker.terminate();
138	    }, timeoutMs);
139	
140	    worker.once("message", (message: LiquidWorkerResult) => {
141	      finish(() => {
142	        if (message.ok) resolve(message.html);
143	        else reject(new Error(message.error));
144	      });
145	      void worker.terminate();
146	    });
147	
148	    worker.once("error", (err: Error) => {
149	      finish(() => reject(err));
150	    });
151	
152	    worker.once("exit", (code: number) => {
153	      finish(() => reject(new Error(`Liquid render worker exited with code ${code}`)));
154	    });
155	  });
156	}

