165	
166	/**
167	 * The minimal shape this walker relies on across every Handlebars AST node
168	 * kind. All fields are optional because different node kinds populate
169	 * different subsets — `ContentStatement`/`CommentStatement` have none of them;
170	 * `MustacheStatement` has `path`/`params`/`hash`/`escaped`;
171	 * `BlockStatement`/`DecoratorBlock`/`PartialBlockStatement` add
172	 * `program`/`inverse`; `PartialStatement` carries its target in `name` rather
173	 * than `path`. Typed structurally rather than against `@types/handlebars`'
174	 * `hbs.AST` union so the walker stays total over node kinds a future
175	 * Handlebars minor might add — an unrecognized node simply contributes no
176	 * usage rather than crashing the lint.
177	 */
178	interface HbsNode {
179	  type?: string;
180	  path?: HbsPath;
181	  name?: HbsPath;
182	  params?: HbsNode[];
183	  hash?: { pairs?: Array<{ value?: HbsNode }> };
184	  escaped?: boolean;
185	  program?: { body?: HbsNode[] };
186	  inverse?: { body?: HbsNode[] };
187	}
188	
189	interface HbsPath {
190	  type?: string;
191	  parts?: string[];
192	  original?: string;
193	  data?: boolean;
194	  depth?: number;
195	}
