204	  return path?.original ?? (path?.parts ?? []).join(".");
205	}
206	
207	/**
208	 * Validate one `PathExpression`'s segments: no prototype-chain segment
209	 * anywhere, and an `@`-data reference only to an allowlisted loop variable.
210	 */
211	function checkPath(path: HbsPath | undefined, violations: string[]): void {
212	  if (path?.type !== "PathExpression") return;
213	  const parts = path.parts ?? [];
214	
215	  if (path.data === true) {
216	    const head = parts[0];
217	    if (head === undefined || !ALLOWED_HANDLEBARS_DATA_VARS.has(head)) {
218	      violations.push(`disallowed data variable "@${pathText(path).replace(/^@/, "")}"`);
219	    }
220	    return;
221	  }
222	
223	  for (const part of parts) {
224	    if (FORBIDDEN_PATH_SEGMENTS.has(part)) {
225	      violations.push(`disallowed path segment "${part}" in "${pathText(path)}"`);
226	    }
227	  }
228	}
229	
230	/**
231	 * Recursively walk a parsed template's statement list, collecting violations.
232	 *
233	 * Every node kind is classified explicitly and the default branch descends
234	 * into `program`/`inverse` rather than ignoring the node, so a construct this
235	 * walker does not recognize can still never hide an unreviewed block body
236	 * beneath it.
237	 *
238	 * @complexity O(n) in AST node count — one pass, no backtracking, no
239	 * re-visiting of a node.
240	 * @overallScore 100/100
241	 */
242	function walkHandlebarsNodes(nodes: HbsNode[], depth: number, violations: string[]): void {
243	  if (depth > MAX_BLOCK_NESTING_DEPTH) {
244	    violations.push(`template nesting exceeds the maximum allowed depth of ${MAX_BLOCK_NESTING_DEPTH}`);
245	    return;
246	  }
247	
248	  for (const node of nodes) {
249	    switch (node.type) {
250	      case "ContentStatement":
251	      case "CommentStatement":
252	        // Literal HTML / `{{! … }}` — no expression, nothing to check.
253	        break;
254	
255	      case "PartialStatement":
256	      case "PartialBlockStatement":
257	        // Handlebars' analogue of Liquid's `include`/`render`: resolves a name
258	        // against the environment's partial registry, which in a filesystem-
259	        // backed setup (the normal way Handlebars is deployed) is a file read,
260	        // and in ANY setup is a jump to source this template did not contain.
261	        // Tovu registers no partials at all and exposes no `registerPartial`
262	        // to a theme, so there is nothing legitimate to resolve — refused as
263	        // syntax rather than left to fail at render.
264	        violations.push(`disallowed partial "${pathText(node.name)}" (partials are not available to themes)`);
265	        break;
266	
267	      case "Decorator":
268	      case "DecoratorBlock":
269	        // `{{#*inline}}`/`{{*decorator}}` mutate the runtime's own program and
270	        // partial resolution from inside template text. No theme need, and the
271	        // single most direct route from "template author" to "compiler
272	        // internals" the language offers.
273	        violations.push(`disallowed decorator "${pathText(node.path)}"`);
274	        break;
275	
276	      case "BlockStatement": {
277	        const name = pathText(node.path);
278	        if (!ALLOWED_HANDLEBARS_BLOCK_HELPERS.has(name)) {
279	          violations.push(`disallowed block helper "${name}"`);
280	        }
281	        for (const param of node.params ?? []) walkExpression(param, depth, violations);
282	        for (const pair of node.hash?.pairs ?? []) {
283	          if (pair.value) walkExpression(pair.value, depth, violations);
284	        }
285	        walkHandlebarsNodes(node.program?.body ?? [], depth + 1, violations);
286	        walkHandlebarsNodes(node.inverse?.body ?? [], depth + 1, violations);
287	        break;
288	      }
289	
290	      case "MustacheStatement": {
291	        const name = pathText(node.path);
292	
293	        if (node.escaped === false && !ALLOWED_HANDLEBARS_RAW_PATHS.has(name)) {
294	          // `{{{x}}}` and `{{&x}}` both parse to `escaped: false`, so this one
295	          // check covers the whole raw-output surface.
296	          violations.push(
297	            `disallowed raw output "{{{${name}}}}" — use "{{${name}}}" (escaped); raw output is permitted only for ${[...ALLOWED_HANDLEBARS_RAW_PATHS].map((p) => `{{{${p}}}}`).join(", ")}`
298	          );
299	        }
300	
301	        if (isInvocation(node) || ALLOWED_HANDLEBARS_HELPERS.has(name)) {
302	          if (!ALLOWED_HANDLEBARS_HELPERS.has(name)) violations.push(`disallowed helper "${name}"`);
303	        } else {
304	          checkPath(node.path, violations);
305	        }
306	
307	        for (const param of node.params ?? []) walkExpression(param, depth, violations);
308	        for (const pair of node.hash?.pairs ?? []) {
309	          if (pair.value) walkExpression(pair.value, depth, violations);
310	        }
311	        break;
312	      }
313	
314	      default:
315	        // Unknown statement kind: contribute no usage, but never let a nested
316	        // body escape review because the wrapper was unrecognized.
317	        walkHandlebarsNodes(node.program?.body ?? [], depth + 1, violations);
318	        walkHandlebarsNodes(node.inverse?.body ?? [], depth + 1, violations);
319	        break;
320	    }
321	  }
322	}
323	
324	/**
325	 * Validate one expression appearing as a helper parameter or hash value —
326	 * a literal, a path, or a `(sub expression)`. A subexpression is a helper
327	 * invocation and is held to the same allowlist as a mustache one, which is
328	 * what stops `{{#if (lookup a b)}}` from smuggling a refused helper into an
329	 * allowed block's arguments.
330	 */
331	function walkExpression(node: HbsNode, depth: number, violations: string[]): void {
332	  if (node.type === "SubExpression") {
333	    const name = pathText(node.path);
334	    if (!ALLOWED_HANDLEBARS_HELPERS.has(name)) violations.push(`disallowed helper "${name}"`);
335	    for (const param of node.params ?? []) walkExpression(param, depth, violations);
336	    for (const pair of node.hash?.pairs ?? []) {
337	      if (pair.value) walkExpression(pair.value, depth, violations);
338	    }
339	    return;
340	  }
341	  if (node.type === "PathExpression") checkPath(node as HbsPath, violations);
