344	/**
345	 * Lint a `.hbs` template source against the Handlebars tier's helper/
346	 * expression allowlist.
347	 *
348	 * Uses `Handlebars.parse()`, which produces an AST and nothing else — no
349	 * compilation to JavaScript, no `new Function`, no execution. That
350	 * distinction is the whole reason this check is safe to run against
351	 * untrusted theme content on the main thread at discovery time: every
352	 * Handlebars RCE class of note begins at *compile*, and a template that fails
353	 * this lint is never compiled at all.
354	 *
355	 * @param source raw `.hbs` template text (untrusted — third-party theme
356	 *   content).
357	 * @returns human-readable violation messages; empty means the template is
358	 *   clean. A Handlebars syntax error is reported the same way (as a single
359	 *   violation message) rather than thrown, so every caller can treat this
360	 *   function as a total, non-throwing predicate — the same contract
361	 *   `lintLiquidTemplate` offers.
362	 * @complexity O(n) in template size — one parse plus one AST walk.
363	 * @overallScore 100/100
364	 */
365	export function lintHandlebarsTemplate(source: string): string[] {
366	  if (source.length > MAX_TEMPLATE_SOURCE_BYTES) {
367	    return [`template exceeds the maximum allowed size of ${MAX_TEMPLATE_SOURCE_BYTES} bytes`];
368	  }
369	
370	  let program: { body?: HbsNode[] };
371	  try {
372	    program = Handlebars.parse(source) as unknown as { body?: HbsNode[] };
373	  } catch (err) {
374	    return [`Handlebars syntax error: ${(err as Error).message}`];
375	  }
376	
377	  const violations: string[] = [];
378	  walkHandlebarsNodes(program.body ?? [], 0, violations);
379	  // De-duplicated because a template can reach the same violation through several branches (a
380	  // depth overrun trips once for a block's `program` and again for its `inverse`; the same
381	  // disallowed helper repeated in a loop body trips per occurrence). The caller folds these into a
382	  // theme's `errors` list for a human to read — the distinct set of problems is the useful signal,
383	  // not the multiplicity.
384	  return [...new Set(violations)];
385	}

361	 * I/O-orchestration function in this file).
362	 *
363	 * Lives here, not in `widgets/resolver-service.ts` or `features/theme/static-render.ts`, because it
364	 * is the one place in the codebase that legitimately needs BOTH `resolveHtmlPageEmbeds` (resolves
365	 * IDs to data) AND `renderHtmlPageBody` (splices IR into HTML) for the SAME nested string — those two
366	 * modules must not depend on each other (`render.ts` already depends on `resolver-service.ts`; the
367	 * reverse would be circular), so only the route layer, which already imports both, can orchestrate
368	 * the resolve-then-splice-then-rescan loop this recursion needs.
369	 *
370	 * Uses {@link withInnerContentFinal}, not `withInnerContent`, for the final splice: an ordinary
371	 * `withInnerContent` call would leave `data-embed-config` intact on the rebuilt element, and the
372	 * CALLER's later `resolveHtmlPageEmbeds`/`renderHtmlPageBody` pass would then rediscover it as a
373	 * fresh, unresolved marker and try to resolve it again — `withInnerContentFinal` strips the marker
374	 * attribute so the already-rendered result is inert to any later scan.
375	 *
376	 * @complexity Bounded by {@link MAX_CONTENT_EMBED_FETCHES} total `findPublishedPostById` calls across
377	 * the whole call tree (the `budget` object is a single mutable counter threaded through every
378	 * recursive call), each followed by an O(n) `resolveHtmlPageEmbeds`/`renderHtmlPageBody` pass over
379	 * that one fetched entity's own body length. Never unbounded, regardless of the input's shape.
380	 *
381	 * Exported for direct testing of guard 3's termination property (`resolve-html-format-content-
382	 * markers.test.ts`) — the testability seam this function's own dependency shape
383	 * ({@link ContentMarkerResolutionDeps}) was narrowed for.
384	 */
385	export async function resolveHtmlFormatContentMarkers(
386	  deps: ContentMarkerResolutionDeps,
387	  html: string,
388	  depth: number,
389	  budget: { remaining: number }
390	): Promise<string> {
391	  if (depth >= MAX_CONTENT_EMBED_DEPTH || budget.remaining <= 0) return html;
392	
393	  const ids = [...new Set(markersOfType(html, "content").map((m) => m.id).filter((id): id is string => id !== undefined))];
394	  if (ids.length === 0) return html;
395	  const idsToFetch = ids.slice(0, budget.remaining);
396	  budget.remaining -= idsToFetch.length;
397	
398	  const replacements = new Map<string, string>();
399	  await Promise.all(
400	    idsToFetch.map(async (id) => {
401	      const entity = await findPublishedPostById({ deps: { repo: deps.postRepo }, input: { workspaceId: deps.workspaceId, id } });
402	      // Missing/unpublished, or `"doc"`-format: leave this id for the final `resolveHtmlPageEmbeds`
403	      // pass — a `"doc"`-format target has nothing here to recurse into, and an unresolved id (guard
404	      // 2) degrades to the same REQ-28 placeholder that pass already produces for any other miss.
405	      if (!entity || entity.bodyFormat !== "html") return;
406	      const ownBody = entity.bodyHtml ?? "";
407	      const nestedHtml = await resolveHtmlFormatContentMarkers(deps, ownBody, depth + 1, budget);
408	      const nestedResolved = await resolveHtmlPageEmbeds({
409	        deps: { entryRepo: deps.entryRepo, postRepo: deps.postRepo, mediaRepo: deps.mediaRepo, transformRepo: deps.transformDefinitionRepo },
410	        input: { workspaceId: deps.workspaceId, html: nestedHtml },
411	      });
412	      replacements.set(id, renderHtmlPageBody(nestedHtml, nestedResolved));
413	    })
414	  );
415	  if (replacements.size === 0) return html;
416	
417	  return substituteMarkers(html, (marker) => {
418	    if (marker.type !== "content" || marker.id === undefined) return undefined;
419	    const replacement = replacements.get(marker.id);
420	    return replacement === undefined ? undefined : withInnerContentFinal(marker, replacement);
421	  });
422	}
