527	  const definition = await getLatestTransformDefinition({
528	    deps: { transformRepo: deps.transformDefinitionRepo },
529	    input: { workspaceId: deps.workspaceId, name: CORE_PUBLIC_TRANSFORM_NAME },
530	  });
