538	/** Walks a TipTap-shaped `bodyJson` tree collecting every ref-based `image` node's `assetId`
539	 * (ADR-027 §4's `{assetId, transformName}` shape) — same walk shape as `resolver-service.ts`'s
540	 * `collectWidgetEmbeds`, kept as a separate local copy since this module has no dependency on
541	 * that one. A legacy `image` node (only `attrs.src`/`attrs.title`, no `assetId`) is simply never
542	 * added — `render.ts`'s `image` case never reads `src`/`title` at all (see that case's own
543	 * comment), so there is nothing for a sizing override to key off for that shape anyway. */
544	function collectImageAssetIds(node: unknown, out: Set<string>): void {
545	  if (Array.isArray(node)) {
546	    for (const child of node) collectImageAssetIds(child, out);
547	    return;
548	  }
549	  if (!isPlainObject(node)) return;
550	  if (node.type === "image" && isPlainObject(node.attrs) && typeof node.attrs.assetId === "string") {
551	    out.add(node.attrs.assetId);
552	  }
553	  if (Array.isArray(node.content)) collectImageAssetIds(node.content, out);
554	}
