556	/**
557	 * Quick-and-dirty public-render sizing fix (owner-directed skip-the-ADR fix, 2026-08-05) —
558	 * resolves each ref-based image node's `MediaRecord.width`/`height`/`cssClass` override ahead of
559	 * `renderSite`, mirroring `resolveWidgetsForRender`/`resolveMediaTransformVersionsForRender`'s own
560	 * "route resolves, `render.ts` stays I/O-free" split (this is the one call site for this
561	 * resolution, same shape as those functions' own doc).
562	 *
563	 * Unlike `resolveMediaTransformVersionsForRender`, there is no single-name shortcut available here
564	 * — width/height/class are genuinely PER-ASSET values, not a property of `(workspaceId,
565	 * transformName)` alone — so this scans `post.bodyJson` for every distinct `assetId` a ref-based
566	 * `image` node references (mirroring `resolveHtmlPageEmbeds`'s own per-id scan for a Page's
567	 * `body_html`), then batch-fetches each one. `MediaRepoPort` (`@jini-ai/cms/media`) has no
568	 * `findByIds`/batch-by-id primitive — only `findById` — the same frozen-contract situation
569	 * `resolvePageWidgets`'s own file header discloses for `EntryRepoPort`; one `findById` per
570	 * distinct `assetId`, run concurrently, is the available primitive at today's real scale (a post
571	 * body with dozens of distinct images would need this widened to a real batch query, same as the
572	 * widget/html-embed resolvers already disclose for their own multi-id case).
573	 *
574	 * Never throws — a lookup that resolves to `null` (deleted, wrong workspace, or an id that was
575	 * never a real asset) is skipped, not thrown; the caller's `image` case already treats an
576	 * `assetId` absent from the returned map as "no override" (omit the attribute), never a crash.
577	 *
578	 * @complexity O(a) over the distinct `assetId`s referenced, each behind one `findById` call
579	 * (run concurrently via `Promise.all`, not serially).
580	 */
581	async function resolveMediaAssetMetadataForRender(
582	  deps: RouteDeps,
583	  post: PostRecord | undefined
584	): Promise<ReadonlyMap<string, MediaAssetRenderMeta>> {
585	  if (!post) return new Map();
586	  const assetIds = new Set<string>();
587	  collectImageAssetIds(post.bodyJson, assetIds);
588	  if (assetIds.size === 0) return new Map();
589	
590	  const entries = await Promise.all(
591	    Array.from(assetIds).map(async (assetId): Promise<readonly [string, MediaAssetRenderMeta] | undefined> => {
592	      const record = await deps.mediaRepo.findById({ workspaceId: deps.workspaceId, id: assetId });
593	      if (!record) return undefined;
594	      return [assetId, { width: record.width, height: record.height, cssClass: record.cssClass }] as const;
595	    })
596	  );
597	  return new Map(entries.filter((entry): entry is readonly [string, MediaAssetRenderMeta] => entry !== undefined));
598	}
