739	        resolveMediaTransformVersionsForRender(deps),
740	        resolveMediaAssetMetadataForRender(deps, post),
741	        buildExtraHead(deps, "post", SITE_TITLE, post),
742	      ]);
743	      res.type("html").send(
744	        await renderSite({
745	          theme,
746	          route: "post",
747	          siteTitle: SITE_TITLE,
748	          posts,
749	          post,
750	          widgets,
751	          pageHtmlEmbeds,
752	          mediaTransformVersions,
753	          mediaAssetMetadata,
754	          extraHead,
755	          siteAssistantEnabled,
756	        }),
757	      );
758	    } catch (err) {
