770	        }
771	
772	        res.status(404).type("html").send("<h1>404 — page not found</h1><p><a href='/'>Home</a></p>");
773	        return;
774	      }
775	      res.status(500).type("html").send("<h1>Site error</h1>");
776	    }
777	  });
778	};

