111	 * why this has to happen first rather than after an `existsSync` probe.
112	 *
113	 * @throws {MarketplaceThemeError} `INVALID_ID` for a malformed id, `NOT_FOUND` if no fixture matches
114	 * in any tier.
115	 * @complexity O(e) in the fixed engine-subfolder count.
116	 */
117	function findMarketplaceTheme(required: {
118	  themesRoot: string;
119	  marketplaceId: string;
120	}): { theme: DiscoveredTheme; tier: ThemeTier } {
121	  const { themesRoot, marketplaceId } = required;
122	  if (!SAFE_THEME_ID.test(marketplaceId)) {
123	    throw new MarketplaceThemeError("INVALID_ID", `theme id '${marketplaceId}' is not a valid theme id`);
124	  }
125	
126	  const marketplaceRoot = join(themesRoot, MARKETPLACE_CATALOG_DIR);
127	  for (const tier of ENGINE_SUBFOLDERS) {
128	    const dir = join(marketplaceRoot, tier, marketplaceId);
129	    if (existsSync(dir)) {
