143	 * @complexity O(s) in the manifest's own (small, bounded) size.
144	 */
145	function rewriteThemeManifestId(required: { themeDir: string; id: string; extra?: Record<string, unknown> }): void {
146	  const { themeDir, id, extra } = required;
147	  const manifestPath = join(themeDir, "theme.json");
148	  const raw = JSON.parse(readFileSync(manifestPath, "utf8")) as Record<string, unknown>;
149	  const updated = { ...raw, id, ...(extra ?? {}) };
150	  writeFileSync(manifestPath, `${JSON.stringify(updated, null, 2)}\n`, "utf8");
151	}
