228	/**
229	 * Download one marketplace fixture: copy it into both the originals catalog and a live tier folder
230	 * under a freshly assigned id, stamp both copies' `theme.json` with that id (the editable copy also
231	 * gets `lineage`), then rescan so the new theme is usable without a server restart.
232	 *
233	 * The two copies are independent files on disk from the moment `cpSync` returns for each — rewriting
234	 * one copy's manifest cannot affect the other. That independence is the whole point of writing both
235	 * rather than one plus a symlink: the catalog copy must stay byte-identical to what shipped even after
236	 * the editable copy is later modified by the user.
237	 *
238	 * @param required.themesRoot - The themes root both the tier folder and the catalog live under
239	 * (`RouteDeps.themesDir`).
240	 * @param required.themes - The live discovered-themes array to refresh via `rescanThemes` — mutated in
241	 * place, matching `rescanThemes`'s own contract.
242	 * @param required.marketplaceId - The marketplace fixture's folder id to download.
243	 * @throws {MarketplaceThemeError} `INVALID_ID` for a malformed id, `NOT_FOUND` if no fixture matches.
244	 * @complexity O(f) in the fixture's own file count (two recursive copies), plus `rescanThemes`'s O(t)
245	 * in the themes root's total theme count.
246	 */
247	export function downloadMarketplaceTheme(
248	  required: { themesRoot: string; themes: DiscoveredTheme[]; marketplaceId: string },
249	  _optional: Record<string, never> = {}
250	): DownloadMarketplaceThemeResult {
251	  const { themesRoot, themes, marketplaceId } = required;
252	  const { theme: fixture, tier } = findMarketplaceTheme({ themesRoot, marketplaceId });
253	
254	  const assignedId = nextAvailableThemeId({ desiredId: fixture.manifest.id, themesRoot, tier });
255	  const suffixed = assignedId !== fixture.manifest.id;
256	
257	  const catalogDir = join(themesRoot, THEME_CATALOG_DIR, tier, assignedId);
258	  const installedDir = join(themesRoot, tier, assignedId);
259	
260	  const filter = (source: string) => !isGeneratedPreviewPath(fixture.dir, source);
261	  cpSync(fixture.dir, catalogDir, { recursive: true, filter });
262	  cpSync(fixture.dir, installedDir, { recursive: true, filter });
263	
264	  rewriteThemeManifestId({ themeDir: catalogDir, id: assignedId });
265	
266	  const lineage: ThemeLineage = {
267	    from: "marketplace",
268	    tier,
269	    version: fixture.manifest.version,
270	    catalog: `${THEME_CATALOG_DIR}/${tier}/${assignedId}`,
271	    marketplaceId,
272	    name: fixture.manifest.name,
273	  };
274	  rewriteThemeManifestId({ themeDir: installedDir, id: assignedId, extra: { lineage } });
275	
276	  const rescan = rescanThemes({ themes, dir: themesRoot });
277	
278	  return { assignedId, suffixed, tier, lineage, rescan };
279	}

