 54	/** Thrown for any path that fails containment. Distinct class so the tool layer can map it to a
 55	 * shape rejection (worth publishing the schema back to the model) rather than an internal error. */
 56	export class ThemePathError extends Error {
 57	  constructor(message: string) {
 58	    super(message);
 59	    this.name = "ThemePathError";
 60	  }
 61	}
 62	
 63	/**
 64	 * Ceiling on one written file, mirroring the Handlebars allowlist's own
 65	 * `MAX_TEMPLATE_SOURCE_BYTES` and the Liquid engine's `parseLimit`. A theme file
 66	 * larger than this is not a theme file.
 67	 */
