 76	/**
 77	 * Directories whose contents are GENERATED build output inside a theme-shaped folder — never real
 78	 * source, and never worth copying or listing as editable. `preview/` is `build-preview.mjs`'s output:
 79	 * a full second copy of a theme's pages and scripts, once per color mode — on `novice` (since deleted)
 80	 * that was 36 of 79 listed files, with `js/main.js`, `preview/dark/js/main.js`, and
 81	 * `preview/light/js/main.js` all showing as "main.js" with nothing to distinguish them, burying the
 82	 * ~30 real source files under three-way duplicates of themselves. Editing one is pointless-to-harmful
 83	 * too: the next `build-preview.mjs` run overwrites it, so the change silently disappears.
 84	 *
 85	 * `screenshots/` is deliberately NOT in this list: those are real marketing assets an author may want
 86	 * to look at or replace, not a copy of the theme's own source — excluding them from the Explore list
 87	 * would hide something real, and excluding them from a marketplace download's catalog copy would make
 88	 * them permanently non-resettable once a user's working copy changed or deleted theirs (that copy is
 89	 * what "reset to original" restores from).
 90	 *
 91	 * The single canonical list — 2026-08-11: this used to be two independent copies, `explore.ts`'s own
 92	 * `GENERATED_DIRS`/`isGenerated` (filtering the Explore file list, given a theme-relative path already
 93	 * in POSIX form) and `marketplace.ts`'s `isGeneratedPreviewPath` (a `cpSync` filter callback, given two
 94	 * ABSOLUTE filesystem paths to relativize itself). Both were answering the identical question —
 95	 * "is this generated preview output" — against the identical directory name, so a third caller would
 96	 * have had to remember to update two places or silently miss one. {@link isGeneratedThemePath} is now
 97	 * that one definition; each caller normalizes its own path shape (already-relative-POSIX for `explore.ts`,
 98	 * `path.relative(fixtureDir, candidate)` for `marketplace.ts`) into the relative string this expects.
 99	 */
100	export const GENERATED_THEME_DIRS: readonly string[] = ["preview"];
101	
102	/**
103	 * Whether a theme-relative path is inside one of {@link GENERATED_THEME_DIRS} — the bare directory
104	 * itself (`"preview"`, the shape `cpSync`'s filter callback sees for the directory entry before
105	 * recursing) or anything under it (`"preview/dark/index.html"`).
106	 *
107	 * Deliberately NOT a prefix match on the raw string (`startsWith("preview")`): that would also exclude
108	 * a merely similarly-named sibling like `preview-notes/`, which is a real author asset with nothing to
109	 * do with generated output. Matching on the full segment (`=== dir` or `startsWith(dir + "/")`) is what
110	 * avoids that false positive.
111	 *
112	 * @param relativePath - A path relative to the theme's own root. Backslash-separated input (a raw
113	 * `path.relative` result on Windows) is normalized to `/` first, so callers on either platform can pass
114	 * their native separator through unchanged.
115	 * @returns `true` iff `relativePath` is `GENERATED_THEME_DIRS[i]` itself or falls under it.
116	 * @throws Never. Pure: no filesystem access, no side effects.
117	 * @complexity Time: O(d·k), d = `GENERATED_THEME_DIRS.length` (a fixed, tiny constant), k = path length.
118	 * @complexity Space: O(k) for the normalized copy.
119	 * @overallScore 100/100
120	 */
121	export function isGeneratedThemePath(relativePath: string): boolean {
122	  // Split on either separator explicitly, not `path.sep` — `sep` is `/` on the POSIX machine this
123	  // runs on today, which would make this a no-op for a `\`-separated string instead of normalizing
124	  // it, silently defeating the cross-platform guarantee this function's own doc comment makes.
125	  const posix = relativePath.split(/[\\/]/).join("/");
126	  return GENERATED_THEME_DIRS.some((dir) => posix === dir || posix.startsWith(`${dir}/`));
127	}
