129	/**
130	 * True when `themeDir` is a direct child of the themes root, or of one of the
131	 * named engine subfolders under it — i.e. exactly the set of locations
132	 * `discoverAllBuiltInThemes()` scans.
133	 *
134	 * This is the SECOND containment question, and it is not implied by the first.
135	 * `resolveThemeFilePath` proves a file is inside its theme's folder; this proves
136	 * that folder is somewhere Tovu recognizes as a theme root at all. Without it, a
137	 * `DiscoveredTheme` fabricated or mutated to carry any other `dir` would grant
138	 * writes wherever that `dir` pointed.
139	 *
140	 * @param required.themeDir - The candidate theme folder (absolute).
141	 * @param required.themesRoot - The configured themes root (`RouteDeps.themesDir`).
142	 * @returns Whether the folder sits at a recognized theme root.
143	 * @complexity O(e) in the engine-subfolder count (a fixed, tiny constant).
144	 * @overallScore 100/100
145	 */
146	export function isRecognizedThemeRoot(
147	  required: { themeDir: string; themesRoot: string },
148	  _optional: Record<string, never> = {}
149	): boolean {
150	  const root = resolve(required.themesRoot);
151	  const parent = dirname(resolve(required.themeDir));
152	  if (parent === root) return true;
153	  return ENGINE_SUBFOLDERS.some((sub) => parent === join(root, sub));
154	}
