156	/** Lexical containment: is `target` at or beneath `base`? Uses `path.relative`, which — unlike a
157	 * prefix match — cannot be satisfied by a sibling whose name merely extends the base's. */
158	function isWithin(base: string, target: string): boolean {
159	  if (base === target) return true;
160	  const rel = relative(base, target);
161	  return rel !== "" && !rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel);
