169	 * resolves outside the theme folder (traversal), and a path whose deepest
170	 * existing ancestor `realpath`s outside the theme folder (symlink escape). The
171	 * theme folder itself is also re-`realpath`ed first, so a themes root reached
172	 * through a symlink still compares correctly rather than failing every write.
173	 *
174	 * @param required.themeDir - The theme's own folder, as recorded by `loadTheme` (`DiscoveredTheme.dir`).
175	 * @param required.themesRoot - The configured themes root, for the recognized-root check.
176	 * @param required.relativePath - The caller-supplied path, relative to the theme folder.
177	 * @returns The absolute, verified-contained path.
178	 * @throws {ThemePathError} On any escape or malformed input.
179	 * @complexity O(d) in the path's directory depth, for the existing-ancestor probe.
180	 * @overallScore 100/100
181	 */
182	export function resolveThemeFilePath(
183	  required: { themeDir: string; themesRoot: string; relativePath: string },
184	  _optional: Record<string, never> = {}
185	): string {
186	  const { themeDir, themesRoot, relativePath } = required;
187	
188	  if (!isRecognizedThemeRoot({ themeDir, themesRoot })) {
189	    throw new ThemePathError(
190	      `theme folder '${themeDir}' is not under a recognized theme root (${themesRoot} or one of its ${ENGINE_SUBFOLDERS.join("/")} subfolders)`
191	    );
192	  }
193	  if (relativePath.length === 0) {
194	    throw new ThemePathError("path is required");
195	  }
196	  if (relativePath.includes("\0")) {
197	    throw new ThemePathError("path must not contain a NUL byte");
198	  }
199	  if (isAbsolute(relativePath)) {
200	    throw new ThemePathError(`path '${relativePath}' must be relative to the theme folder, not absolute`);
201	  }
202	
203	  // `realpath` the base so a themes root reached through a symlink (a container
204	  // bind-mount, a dev checkout symlinked into place) compares against the same
205	  // canonical form the ancestor probe below produces.
206	  const base = existsSync(themeDir) ? realpathSync(themeDir) : resolve(themeDir);
207	  const target = resolve(base, relativePath);
208	
209	  if (!isWithin(base, target)) {
210	    throw new ThemePathError(`path '${relativePath}' resolves outside the theme folder`);
211	  }
212	
213	  // Symlink-aware re-check. The target may not exist (a write creating a new
214	  // file), so walk up to the deepest ancestor that does, canonicalize THAT, and
215	  // require it to still be inside the theme folder. A symlinked directory
216	  // anywhere along the chain is caught here even though it is lexically clean.
217	  let probe = target;
218	  for (let i = 0; i < MAX_WALK_DEPTH * 4 && !existsSync(probe); i += 1) {
219	    const parent = dirname(probe);
220	    if (parent === probe) break;
221	    probe = parent;
222	  }
223	  if (existsSync(probe)) {
224	    const realProbe = realpathSync(probe);
225	    if (!isWithin(base, realProbe)) {
226	      throw new ThemePathError(`path '${relativePath}' resolves outside the theme folder through a symbolic link`);
227	    }
228	  }
229	
230	  return target;
231	}
232	
233	/**
234	 * List every regular file under a theme's folder, as paths relative to it.
235	 *
236	 * Descends real directories only — a symlinked directory is not followed, so a
237	 * link out of the folder can neither enumerate nor leak anything beyond it.
238	 * Bounded by {@link MAX_LISTED_FILES} and {@link MAX_WALK_DEPTH}.
239	 *
240	 * @param required.themeDir - The theme's own folder.
241	 * @param required.themesRoot - The configured themes root, for the recognized-root check.
242	 * @returns Relative paths, sorted, using `/` separators.
243	 * @throws {ThemePathError} If the folder is not at a recognized theme root.
244	 * @complexity O(n) in the file count under the folder.
245	 * @overallScore 100/100
246	 */
247	export function listThemeFiles(
248	  required: { themeDir: string; themesRoot: string },
249	  _optional: Record<string, never> = {}
250	): string[] {
251	  const { themeDir, themesRoot } = required;
252	  if (!isRecognizedThemeRoot({ themeDir, themesRoot })) {
253	    throw new ThemePathError(`theme folder '${themeDir}' is not under a recognized theme root`);
254	  }
255	  if (!existsSync(themeDir)) return [];
256	
257	  const base = realpathSync(themeDir);
258	  const found: string[] = [];
259	
260	  const walk = (dir: string, depth: number): void => {
261	    if (depth > MAX_WALK_DEPTH || found.length >= MAX_LISTED_FILES) return;
262	    for (const name of readdirSync(dir)) {
263	      if (found.length >= MAX_LISTED_FILES) return;
264	      const full = join(dir, name);
265	      // `lstat` semantics via `statSync(..., {throwIfNoEntry})` would follow the
266	      // link; read the link status explicitly instead so a symlink is neither
267	      // descended nor reported as a file.
268	      const stat = statSync(full, { throwIfNoEntry: false });
269	      if (!stat) continue;
270	      const isLink = realpathSync(full) !== full;
271	      if (isLink) continue;
272	      if (stat.isDirectory()) walk(full, depth + 1);
273	      else if (stat.isFile()) found.push(relative(base, full).split(sep).join("/"));
274	    }
275	  };
276	  walk(base, 0);
277	
278	  return found.sort();
279	}
280	
281	/**
282	 * Read one file inside a theme's folder as UTF-8 text.
283	 *
284	 * @throws {ThemePathError} On any containment failure, or when the path is not a regular file.
285	 * @complexity O(s) in the file size.
286	 * @overallScore 100/100
287	 */
288	export function readThemeFile(
289	  required: { themeDir: string; themesRoot: string; relativePath: string },
290	  _optional: Record<string, never> = {}
291	): string {
292	  const target = resolveThemeFilePath(required);
293	  const stat = statSync(target, { throwIfNoEntry: false });
294	  if (!stat) throw new ThemePathError(`file '${required.relativePath}' does not exist in this theme`);
295	  if (!stat.isFile()) throw new ThemePathError(`path '${required.relativePath}' is not a regular file`);
296	  if (stat.size > MAX_THEME_FILE_BYTES) {
297	    throw new ThemePathError(`file '${required.relativePath}' exceeds the ${MAX_THEME_FILE_BYTES}-byte readable limit`);
298	  }
299	  return readFileSync(target, "utf8");
300	}
301	
302	/**
303	 * Write (create or overwrite) one file inside a theme's folder, creating any
304	 * intermediate directories — which are themselves inside the folder, since the
305	 * resolved path already passed containment.
306	 *
307	 * @returns The absolute path written.
308	 * @throws {ThemePathError} On any containment failure, an oversized body, or a
309	 * target that exists and is not a regular file.
310	 * @complexity O(s) in the content size.
311	 * @overallScore 100/100
312	 */
313	export function writeThemeFile(
314	  required: { themeDir: string; themesRoot: string; relativePath: string; content: string },
315	  _optional: Record<string, never> = {}
316	): string {
317	  const target = resolveThemeFilePath(required);
318	  if (Buffer.byteLength(required.content, "utf8") > MAX_THEME_FILE_BYTES) {
319	    throw new ThemePathError(`content exceeds the ${MAX_THEME_FILE_BYTES}-byte per-file limit`);
320	  }
321	  const existing = statSync(target, { throwIfNoEntry: false });
322	  if (existing && !existing.isFile()) {
323	    throw new ThemePathError(`path '${required.relativePath}' exists and is not a regular file`);
324	  }
325	  mkdirSync(dirname(target), { recursive: true });
326	  writeFileSync(target, required.content, "utf8");
327	  return target;
328	}
329	
330	/**
331	 * Shared containment + preflight for {@link copyThemeFile}/{@link renameThemeFile}: resolves both
332	 * the source and destination through {@link resolveThemeFilePath} (so a destination built from
333	 * operator input — a rename's new filename — is validated exactly as strictly as a write target),
334	 * confirms the source is a regular file within the size ceiling, and refuses to clobber an existing
335	 * destination.
336	 *
337	 * Deliberately does NOT decode either path through `readFileSync(…, "utf8")` /
338	 * `writeFileSync(…, "utf8")` the way {@link readThemeFile}/{@link writeThemeFile} do: a binary asset
339	 * (a font, an image) round-tripped through UTF-8 would come back byte-corrupted, and copy/rename
340	 * must work on every file in a theme's folder, not only the text-editable ones.
341	 */
342	function resolveCopyOrRenameTargets(
343	  required: { themeDir: string; themesRoot: string; sourcePath: string; destPath: string }
344	): { source: string; dest: string } {
345	  const { themeDir, themesRoot, sourcePath, destPath } = required;
346	  const source = resolveThemeFilePath({ themeDir, themesRoot, relativePath: sourcePath });
347	  const sourceStat = statSync(source, { throwIfNoEntry: false });
348	  if (!sourceStat) throw new ThemePathError(`file '${sourcePath}' does not exist in this theme`);
349	  if (!sourceStat.isFile()) throw new ThemePathError(`path '${sourcePath}' is not a regular file`);
350	  if (sourceStat.size > MAX_THEME_FILE_BYTES) {
351	    throw new ThemePathError(`file '${sourcePath}' exceeds the ${MAX_THEME_FILE_BYTES}-byte limit`);
352	  }
353	
354	  const dest = resolveThemeFilePath({ themeDir, themesRoot, relativePath: destPath });
355	  if (existsSync(dest)) {
356	    throw new ThemePathError(`path '${destPath}' already exists in this theme`);
357	  }
358	
359	  return { source, dest };
360	}
361	
362	/**
363	 * Duplicate one file inside a theme's folder to a new path also inside it, byte-for-byte.
364	 *
365	 * @returns The absolute destination path written.
366	 * @throws {ThemePathError} On containment failure for either path, a missing/oversized/non-file
367	 * source, or a destination that already exists.
368	 * @complexity O(s) in the file size.
369	 * @overallScore 100/100
370	 */
371	export function copyThemeFile(
372	  required: { themeDir: string; themesRoot: string; sourcePath: string; destPath: string },
373	  _optional: Record<string, never> = {}
374	): string {
375	  const { source, dest } = resolveCopyOrRenameTargets(required);
376	  mkdirSync(dirname(dest), { recursive: true });
377	  try {
378	    // `COPYFILE_EXCL` closes the TOCTOU window `resolveCopyOrRenameTargets`' own `existsSync(dest)`
379	    // check leaves open: two concurrent copy requests both landing on the same auto-suffixed name
380	    // (e.g. two rapid clicks generating `about-1.html` from the same source) would otherwise both
381	    // pass that pre-check and race to overwrite one another. `copyFileSync` has an atomic
382	    // exclusive-write mode for exactly this; `renameSync` (below) does not, so the identical race is
383	    // a known, narrower, accepted gap there — this domain is a single authenticated operator's admin
384	    // tool, not a multi-tenant race target, and every other write in this file already accepts the
385	    // same class of risk (`writeThemeFile` has no equivalent guard at all).
386	    copyFileSync(source, dest, fsConstants.COPYFILE_EXCL);
387	  } catch (err) {
388	    if ((err as NodeJS.ErrnoException).code === "EEXIST") {
389	      throw new ThemePathError(`path '${required.destPath}' already exists in this theme`);
390	    }
391	    throw err;
392	  }
393	  return dest;
394	}
395	
396	/**
397	 * Move (rename) one file within a theme's folder, byte-for-byte.
398	 *
399	 * @returns The absolute destination path.
400	 * @throws {ThemePathError} On containment failure for either path, a missing/oversized/non-file
401	 * source, or a destination that already exists.
402	 * @complexity O(1) — same-filesystem rename, not a copy.
403	 * @overallScore 100/100
404	 */
405	export function renameThemeFile(
406	  required: { themeDir: string; themesRoot: string; sourcePath: string; destPath: string },
407	  _optional: Record<string, never> = {}
408	): string {
409	  const { source, dest } = resolveCopyOrRenameTargets(required);
410	  mkdirSync(dirname(dest), { recursive: true });
411	  renameSync(source, dest);
412	  return dest;
413	}

