 1	{%- comment -%}
 2	  Storefront — home. A Shopify-style landing: hero, then a featured product
 3	  grid pulled straight from the store plugin's real data, then a small
 4	  journal teaser for regular posts (Tovu's blog content is a separate
 5	  system from products — this theme surfaces both).
 6	{%- endcomment -%}
 7	{% render_block component: "tovu/site-header", tagline: "Small batch goods." %}
 8	
 9	<section class="hero">
10	  <div class="wrap">
11	    <p class="hero__eyebrow">NEW ARRIVALS</p>
12	    <h1 class="hero__title">Made slow. Built to last.</h1>
13	    <p class="hero__sub">Every product below is real, seeded data from Tovu's sample store plugin — not hardcoded into this theme.</p>
14	    <a class="btn btn--primary" href="/products">Shop all products</a>
15	  </div>
16	</section>
17	
18	<section class="products">
19	  <div class="wrap">
20	    <h2 class="section-title">Featured</h2>
21	    {%- if products.size == 0 -%}
22	      <p class="products__empty">No products available — the store plugin isn't enabled in this runtime.</p>
23	    {%- else -%}
24	      <ul class="product-grid">
25	        {%- for product in products -%}
26	          <li class="product-card">
27	            <a href="/products/{{ product.id }}">
28	              <div class="product-card__image" aria-hidden="true"></div>
29	              <h3 class="product-card__title">{{ product.title }}</h3>
30	              <p class="product-card__price">{{ product.priceFormatted }}</p>
31	              {%- if product.stock == 0 -%}
32	                <p class="product-card__stock product-card__stock--out">Sold out</p>
33	              {%- endif -%}
34	            </a>
35	          </li>
36	        {%- endfor -%}
37	      </ul>
38	    {%- endif -%}
39	  </div>
40	</section>
41	
42	{%- if posts.size > 0 -%}
43	<section class="journal-teaser">
44	  <div class="wrap">
45	    <h2 class="section-title">From the journal</h2>
46	    <ul class="journal-teaser__list">
47	      {%- assign shown = 0 -%}
48	      {%- for post in posts -%}
49	        {%- assign shown = shown | plus: 1 -%}
50	        {%- if shown <= 3 -%}
51	          <li><a href="/{{ post.slug }}">{{ post.title }}</a></li>
52	        {%- endif -%}
53	      {%- endfor -%}
54	    </ul>
55	  </div>
56	</section>
57	{%- endif -%}
